export interface Stay01Room {
  id: string;
  name: string;
  description: string;
  guests: number;
  area: string;
  bed: string;
  amount?: number;
  imageSrc?: string;
  imageAlt?: string;
  href?: string;
}
export interface Stay01Request {
  arrival: string;
  departure: string;
  guests: number;
  nights: number;
}
export interface Stay01Draft {
  arrival: string;
  departure: string;
  guests: string;
}
export interface Stay01Detail {
  id: string;
  title: string;
  description: string;
}
export interface Stay01Props {
  name?: string;
  eyebrow?: string;
  title?: string;
  titleAccent?: string;
  description?: string;
  location?: string;
  heroSrc?: string;
  heroAlt?: string;
  imageCredit?: string;
  rooms?: readonly Stay01Room[];
  details?: readonly Stay01Detail[];
  minDate?: string;
  maxDate?: string;
  maxNights?: number;
  currency?: string;
  locale?: string;
  roomHref?: (
    room: Stay01Room,
    request: Stay01Request | null,
  ) => string | undefined;
  contactHref?: string;
  notice?: string;
}
