export function dateDay(value: string): number | null {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value) || Number(value.slice(0, 4)) < 1)
    return null;
  const timestamp = Date.parse(`${value}T00:00:00.000Z`);
  return Number.isFinite(timestamp) &&
    new Date(timestamp).toISOString().slice(0, 10) === value
    ? timestamp / 86400000
    : null;
}
export function nextStayDate(value: string): string | undefined {
  const day = dateDay(value);
  if (day === null) return undefined;
  const next = new Date((day + 1) * 86400000).toISOString().slice(0, 10);
  return dateDay(next) === null ? undefined : next;
}
export function prepareStayRequest(
  draft: Stay01Draft,
  options: {
    minDate?: string;
    maxDate?: string;
    maxNights?: number;
    maxGuests: number;
  },
) {
  const errors: Partial<Record<keyof Stay01Draft, string>> = {};
  const arrival = dateDay(draft.arrival),
    departure = dateDay(draft.departure);
  const min = options.minDate ? dateDay(options.minDate) : null,
    max = options.maxDate ? dateDay(options.maxDate) : null;
  if (
    (options.minDate && min === null) ||
    (options.maxDate && max === null) ||
    (min !== null && max !== null && min >= max) ||
    !Number.isSafeInteger(options.maxNights ?? 30) ||
    (options.maxNights ?? 30) < 1
  )
    throw new RangeError("Invalid stay date constraints.");
  if (arrival === null) errors.arrival = "Choose a valid arrival date.";
  else if (min !== null && arrival < min)
    errors.arrival = "Choose a later arrival date.";
  if (departure === null) errors.departure = "Choose a valid departure date.";
  else if (arrival !== null && departure <= arrival)
    errors.departure = "Departure must be after arrival.";
  else if (arrival !== null && departure - arrival > (options.maxNights ?? 30))
    errors.departure = `Choose a stay of ${options.maxNights ?? 30} nights or fewer.`;
  if (max !== null && departure !== null && departure > max)
    errors.departure = "Choose an earlier departure date.";
  if (max !== null && arrival !== null && arrival >= max)
    errors.arrival = "Choose an earlier arrival date.";
  const guests = Number(draft.guests);
  if (
    !/^\d+$/.test(draft.guests) ||
    !Number.isSafeInteger(guests) ||
    guests < 1 ||
    guests > options.maxGuests
  )
    errors.guests = "Choose a supported number of guests.";
  const request: Stay01Request | null = Object.keys(errors).length
    ? null
    : {
        arrival: draft.arrival,
        departure: draft.departure,
        guests,
        nights: departure! - arrival!,
      };
  return { errors, request };
}
export function validateStay(
  rooms: readonly Stay01Room[],
  details: readonly Stay01Detail[],
) {
  for (const collection of [rooms, details]) {
    const ids = new Set<string>();
    for (const item of collection) {
      if (!/^[a-zA-Z0-9][a-zA-Z0-9_-]*$/.test(item.id) || ids.has(item.id))
        throw new RangeError("Stay items need unique anchor-safe IDs.");
      ids.add(item.id);
    }
  }
  for (const room of rooms)
    if (
      !Number.isSafeInteger(room.guests) ||
      room.guests < 1 ||
      room.guests > 20 ||
      (room.amount !== undefined &&
        (!Number.isFinite(room.amount) || room.amount < 0))
    )
      throw new RangeError("Invalid room capacity or indicative rate.");
}

.stay01 {
  --stay01-section-gap: var(--space-12);
  --stay01-column-gap: var(--space-10);
  --stay01-plan-surface: color-mix(
    in oklch,
    var(--brand-primary) 5%,
    var(--surface-base)
  );
  padding: var(--space-6) var(--container-padding-lg) var(--space-8);
  background: var(--background-primary);
  color: var(--text-primary);
  font-family: var(--font-family-body);
}
.stay01 *,
.stay01 *::before,
.stay01 *::after {
  box-sizing: border-box;
}
.stay01 :is(h1, h2, h3, p, figure, ul) {
  margin: 0;
}
.stay01-inner {
  max-width: var(--container-max-width);
  margin-inline: auto;
}
.stay01 a {
  color: inherit;
  text-underline-offset: var(--space-1);
}
.stay01 a:focus-visible,
.stay01 :is(.stay01-rooms, .stay01-planner):focus-visible {
  outline: var(--focus-ring-width) solid var(--focus-ring-color);
  outline-offset: var(--focus-ring-offset);
}
.stay01 :is(header, section, figure) {
  scroll-margin-block-start: var(--space-7);
}
.stay01 .stay01-masthead {
  gap: var(--space-5);
  padding-block-end: var(--space-5);
  border-block-end: var(--border-width-thin) solid var(--border-default);
}
.stay01-brand {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  text-decoration: none;
  font-family: var(--font-family-display);
  font-size: var(--font-size-2xl);
  letter-spacing: var(--letter-spacing-tight);
}
.stay01-brand span {
  font-family: var(--font-family-body);
  font-size: var(--typography-micro-size);
  letter-spacing: var(--letter-spacing-widest);
  color: var(--text-muted);
}
.stay01-masthead nav {
  font-size: var(--typography-caption-size);
}
.stay01-masthead nav .flex {
  gap: var(--space-6);
  align-items: center;
}
.stay01-masthead nav a {
  text-decoration: none;
}
.stay01-masthead nav a:hover {
  text-decoration: underline;
}
.stay01-nav-action {
  padding: var(--space-3) var(--space-4);
  border: var(--border-width-thin) solid var(--border-default);
  border-radius: var(--button-radius);
}
.stay01-nav-action span {
  margin-inline-start: var(--space-4);
}
.stay01-kicker {
  font-size: var(--typography-micro-size);
  letter-spacing: var(--letter-spacing-widest);
  color: var(--text-muted);
}
.stay01-intro {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: var(--stay01-column-gap);
  padding-block: var(--space-8);
}
.stay01-intro > div:first-child {
  flex: 1 1 64%;
  min-width: 0;
}
.stay01 .stay01-intro h1 {
  margin-block-start: var(--space-5);
  font-size: var(--typography-hero-size);
  line-height: var(--typography-heading-lineheight);
  letter-spacing: var(--typography-heading-letterspacing);
  overflow-wrap: anywhere;
}
.stay01-intro h1 em {
  display: block;
  font-weight: inherit;
}
.stay01-intro-note {
  flex: 0 1 30%;
  min-width: 0;
  padding-block-end: var(--space-2);
}
.stay01-intro-note > p {
  color: var(--text-secondary);
  font-size: var(--typography-caption-size);
  line-height: var(--line-height-relaxed);
}
.stay01-intro-note > span {
  display: block;
  margin-block-start: var(--space-6);
  font-size: var(--typography-micro-size);
  color: var(--text-muted);
  letter-spacing: var(--letter-spacing-wide);
}
.stay01-landscape > .media {
  border-radius: var(--media-radius);
  overflow: hidden;
}
.stay01-landscape figcaption {
  display: flex;
  justify-content: space-between;
  gap: var(--space-4);
  padding-block-start: var(--space-3);
  color: var(--text-muted);
  font-size: var(--typography-micro-size);
  letter-spacing: var(--letter-spacing-wide);
}
.stay01-planner {
  display: flex;
  gap: var(--stay01-column-gap);
  padding: var(--space-6);
  margin-block-start: var(--space-6);
  background: var(--surface-card);
  border: var(--border-width-thin) solid var(--border-default);
  border-radius: var(--card-radius);
}
.stay01-planner-intro {
  flex: 1 1 34%;
  min-width: 0;
}
.stay01 .stay01-planner h2 {
  margin-block-start: var(--space-3);
  font-size: var(--font-size-2xl);
  line-height: var(--typography-heading-lineheight);
}
.stay01-planner-intro > p:last-child {
  margin-block-start: var(--space-3);
  font-size: var(--typography-caption-size);
  color: var(--text-muted);
}
.stay01-planner form {
  flex: 1 1 66%;
  min-width: 0;
}
.stay01-fields {
  display: flex;
  gap: var(--space-4);
  align-items: start;
}
.stay01-fields > .form-field {
  flex: 1 1 35%;
  min-width: 0;
}
.stay01-fields > .form-field:last-child {
  flex-basis: 24%;
}
.stay01-fields .input,
.stay01-fields .select {
  min-width: 0;
  width: 100%;
}
.stay01 .stay01-planner-bottom {
  margin-block-start: var(--space-5);
  gap: var(--space-5);
}
.stay01-planner-bottom > p {
  color: var(--text-muted);
  font-size: var(--typography-micro-size);
  line-height: var(--line-height-relaxed);
}
.stay01-planner-bottom .btn {
  gap: var(--space-6);
}
.stay01-rooms {
  padding-block: var(--stay01-section-gap);
}
.stay01 .stay01-section-heading {
  gap: var(--space-5);
  margin-block-end: var(--space-6);
}
.stay01-section-heading h2,
.stay01-details-intro h2 {
  margin-block-start: var(--space-4);
  font-size: var(--website-title-size);
  line-height: var(--typography-heading-lineheight);
}
.stay01-result-note {
  text-align: end;
  font-size: var(--typography-caption-size);
  color: var(--text-muted);
}
.stay01-result-note > p + p {
  margin-block-start: var(--space-2);
}
.stay01-result-note .btn {
  margin-block-start: var(--space-2);
}
.stay01-update {
  padding: var(--space-4);
  margin-block-end: var(--space-5);
  background: var(--brand-primary-muted);
  color: var(--text-primary);
  font-size: var(--typography-caption-size);
  border-radius: var(--form-radius);
}
.stay01-room-list {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-5);
}
.stay01-room {
  flex: 1 1 30%;
  max-width: calc((100% - var(--space-5) * 2) / 3);
  min-width: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: var(--card-background);
  border: var(--border-width-thin) solid var(--card-border);
  border-radius: var(--card-radius);
  box-shadow: var(--card-shadow);
}
.stay01-room-art {
  position: relative;
  height: calc(var(--space-4) * 13);
  overflow: hidden;
  background: var(--stay01-plan-surface);
}
.stay01-room-art > .media,
.stay01-room-art img {
  width: 100%;
  height: 100%;
}
.stay01-plan {
  display: block;
  width: 100%;
  height: 100%;
  padding: var(--space-4);
  color: var(--text-secondary);
}
.stay01-plan-bed {
  fill: var(--brand-primary-muted);
  stroke: currentColor;
}
.stay01-plan-window {
  stroke: var(--brand-primary);
}
.stay01-plan-guide {
  stroke: var(--border-strong);
}
.stay01-room-art > span {
  position: absolute;
  inset-inline-start: var(--space-4);
  inset-block-end: var(--space-3);
  font-family: var(--font-family-mono);
  font-size: var(--typography-micro-size);
  letter-spacing: var(--letter-spacing-wide);
  color: var(--text-muted);
}
.stay01-room-copy {
  display: flex;
  flex-direction: column;
  flex: 1;
  gap: var(--space-4);
  padding: var(--space-5);
}
.stay01-room-copy h3 {
  font-size: var(--font-size-2xl);
  line-height: var(--typography-heading-lineheight);
}
.stay01-room-copy > p {
  flex: 1;
  color: var(--text-secondary);
  font-size: var(--typography-caption-size);
  line-height: var(--line-height-relaxed);
}
.stay01-room-copy ul {
  list-style: none;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2) var(--space-4);
  font-size: var(--typography-micro-size);
  color: var(--text-muted);
}
.stay01-room-copy li + li::before {
  content: "/";
  margin-inline-end: var(--space-4);
  color: var(--border-strong);
}
.stay01-room-bottom {
  display: flex;
  justify-content: space-between;
  align-items: end;
  gap: var(--space-4);
  padding-block-start: var(--space-4);
  border-block-start: var(--border-width-thin) solid var(--border-default);
}
.stay01-rate-label {
  display: block;
  margin-block-end: var(--space-2);
  font-size: var(--typography-micro-size);
  color: var(--text-muted);
}
.stay01-rate-unit {
  display: block;
  margin-block-start: var(--space-1);
  font-size: var(--typography-micro-size);
  color: var(--text-muted);
}
.stay01-room-bottom .price {
  font-family: var(--font-family-display);
  font-size: var(--font-size-2xl);
}
.stay01-empty {
  padding: var(--space-8);
  border: var(--border-width-thin) solid var(--border-default);
  border-radius: var(--card-radius);
  text-align: center;
}
.stay01-empty p {
  margin-block-start: var(--space-3);
  color: var(--text-muted);
}
.stay01-details {
  display: flex;
  gap: var(--stay01-column-gap);
  padding: var(--space-8);
  border-radius: var(--card-radius);
  background: var(--surface-base);
  border: var(--border-width-thin) solid var(--border-default);
}
.stay01-details-intro {
  flex: 1 1 44%;
  min-width: 0;
}
.stay01-details-intro a {
  display: inline-block;
  margin-block-start: var(--space-6);
  font-size: var(--typography-caption-size);
}
.stay01-detail-list {
  flex: 1 1 56%;
  min-width: 0;
}
.stay01-detail-list article {
  display: flex;
  gap: var(--space-5);
  padding-block: var(--space-5);
  border-block-end: var(--border-width-thin) solid var(--border-default);
}
.stay01-detail-list article:first-child {
  padding-block-start: 0;
}
.stay01-detail-list article:last-child {
  padding-block-end: 0;
  border-block-end: 0;
}
.stay01-detail-number {
  color: var(--brand-primary);
  font-family: var(--font-family-display);
  font-size: var(--font-size-lg);
}
.stay01-detail-list h3 {
  font-size: var(--font-size-xl);
}
.stay01-detail-list p {
  margin-block-start: var(--space-3);
  color: var(--text-muted);
  font-size: var(--typography-caption-size);
  line-height: var(--line-height-relaxed);
}
.stay01 .stay01-footer {
  margin-block-start: var(--stay01-section-gap);
  padding-block-start: var(--space-6);
  gap: var(--space-6);
  border-block-start: var(--border-width-thin) solid var(--border-default);
  font-size: var(--typography-caption-size);
}
.stay01-signature {
  font-family: var(--font-family-display);
  font-size: var(--font-size-3xl);
}
.stay01-footer p {
  margin-block-start: var(--space-3);
  max-width: var(--content-width-readable);
  font-size: var(--typography-micro-size);
  color: var(--text-muted);
}
@media (max-width: 900px) {
  .stay01 {
    padding-inline: var(--container-padding);
    --stay01-column-gap: var(--space-6);
    --stay01-section-gap: var(--space-9);
  }
  .stay01-planner {
    flex-direction: column;
  }
  .stay01-planner-intro br {
    display: none;
  }
  .stay01-room {
    flex-basis: 45%;
    max-width: calc((100% - var(--space-5)) / 2);
  }
  .stay01-details {
    padding: var(--space-6);
  }
}
@media (max-width: 600px) {
  .stay01-intro {
    flex-direction: column;
    align-items: stretch;
    gap: var(--space-5);
    padding-block: var(--space-6);
  }
  .stay01-intro-note > span {
    margin-block-start: var(--space-3);
  }
  .stay01-masthead nav .flex {
    gap: var(--space-4);
  }
  .stay01-fields {
    flex-wrap: wrap;
  }
  .stay01-fields > .form-field {
    flex-basis: 45%;
  }
  .stay01-fields > .form-field:last-child {
    flex-basis: 100%;
  }
  .stay01-room {
    flex-basis: 100%;
    max-width: 100%;
  }
  .stay01-result-note {
    text-align: start;
  }
  .stay01-details {
    flex-direction: column;
  }
  .stay01-landscape figcaption {
    flex-direction: column;
    gap: var(--space-2);
  }
  .stay01-landscape .media {
    aspect-ratio: var(--media-aspect-video);
  }
}
